{"code": "import numpy as np
import pandas as pd
from catboost import CatBoostClassifier

def fit(train: pd.DataFrame, target: str, seed: int) -> object:
    X = train.drop(columns=[target])
    y = train[target]

    # Create interaction features: country * numeric features
    country_cols = ['france', 'germany', 'spain']
    gender_cols = ['female', 'male']
    numeric_cols = ['age', 'balance', 'creditscore', 'estimatedsalary']

    for c in country_cols:
        for n in numeric_cols:
            X[f'{c}_{n}'] = X[c] * X[n]
    for g in gender_cols:
        for n in numeric_cols:
            X[f'{g}_{n}'] = X[g] * X[n]

    model = CatBoostClassifier(
        iterations=200,
        learning_rate=0.05,
        depth=6,
        l2_leaf_reg=3,
        loss_function='Logloss',
        random_seed=seed,
        verbose=False,
        thread_count=2
    )
    model.fit(X, y)
    return model

def predict(model: object, X: pd.DataFrame) -> np.ndarray:
    # Create the same interaction features
    country_cols = ['france', 'germany', 'spain']
    gender_cols = ['female', 'male']
    numeric_cols = ['age', 'balance', 'creditscore', 'estimatedsalary']

    for c in country_cols:
        for n in numeric_cols:
            X[f'{c}_{n}'] = X[c] * X[n]
    for g in gender_cols:
        for n in numeric_cols:
            X[f'{g}_{n}'] = X[g] * X[n]

    return model.predict_proba(X)[:, 1]", "note": "Baseline with interaction features: country*numeric and gender*numeric"}
